import{_ as a,d as i,e as t,y as n}from"./chunks/framework.D7CAgLCq.js";const g=JSON.parse('{"title":"Downloads and citation","description":"Download the English reference edition, the Chinese v2 text it translates, and the current Chinese text, and distinguish the English reading edition from the original supplied translation.","frontmatter":{"title":"Downloads and citation","description":"Download the English reference edition, the Chinese v2 text it translates, and the current Chinese text, and distinguish the English reading edition from the original supplied translation."},"headers":[],"relativePath":"en/downloads.md","filePath":"en/downloads.md"}'),s={name:"en/downloads.md"};function o(r,e,d,l,h,c){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="downloads-and-citation" tabindex="-1">Downloads and citation <a class="header-anchor" href="#downloads-and-citation" aria-label="Permalink to &quot;Downloads and citation&quot;">​</a></h1><p><strong>Xikari: On Conditions, Structure, and Transformation</strong>, by Xikari, theory v2, November 2026. The English reference edition translates the Chinese v2 text of 16 November 2026 and preserves its numbered sections and part anchors. The Chinese text has since been reworded, with the same structure and section numbers. The Chinese governs where the two differ.</p><h2 id="complete-files" tabindex="-1">Complete files <a class="header-anchor" href="#complete-files" aria-label="Permalink to &quot;Complete files&quot;">​</a></h2><ul><li><a href="/xi-kari-skill/handbook/downloads/Xikari-On-Conditions-Structure-and-Transformation.md" download>English reference reading edition — Markdown</a></li><li><a href="/xi-kari-skill/handbook/downloads/xikari-conditions-en.original.md" download>Original supplied English file — unchanged bytes</a></li><li><a href="/xi-kari-skill/handbook/downloads/Xikari-条件结构与转化论.v2.md" download>Chinese v2 text of 16 November 2026 — Markdown</a></li><li><a href="/xi-kari-skill/handbook/downloads/Xikari-条件结构与转化论.md" download>Current Chinese text, reworded on 19 November 2026 — Markdown</a></li><li><a href="/xi-kari-skill/handbook/downloads/Xikari-条件结构与转化论.v1.docx" download>Earlier Chinese v1 Word reading edition — archive</a></li><li><a href="https://github.com/xi-kari/xi-kari-skill/releases/latest" target="_blank" rel="noreferrer">Xikari Skill releases</a></li></ul><p>This translation and the reading notes follow the Chinese v2 text of 16 November 2026. The current Chinese text changes only the wording: its sentences are plainer, and each code now stands at the end of the heading that defines it and in a table in Appendix B. Its parts, sections and section numbers are those of v2.</p><p>The Word file is an earlier v1 artifact, <strong>not a v2 Word edition</strong>. Use the Markdown files or the current <a href="/xi-kari-skill/handbook/en/theory/">English reading pages</a> for the revised theory.</p><p>The English reading edition normalizes the supplied translation for navigation and preserves its translator’s notes. Those notes are identified as translation notes, not additional statements by the author. The original supplied file is separately available for comparison.</p><h2 id="cite-a-source-section" tabindex="-1">Cite a source section <a class="header-anchor" href="#cite-a-source-section" aria-label="Permalink to &quot;Cite a source section&quot;">​</a></h2><p>Include the author, title, theory version, section number, language/edition, and the section link. For example:</p><blockquote><p>Xikari, <em>On Conditions, Structure, and Transformation</em>, theory v2 (November 2026), §3.3, English reference edition.</p></blockquote><p>The link to <a href="/xi-kari-skill/handbook/en/theory/part-03.html#section-3-3">§3.3</a> opens the same numbered section as the <a href="/xi-kari-skill/handbook/theory/part-03.html#section-3-3">Chinese source</a>. For a case’s factual claim, cite the report or study linked from the case page. The site’s guides are derived reading aids and should not be quoted as the author’s original definitions.</p><h2 id="text-identities" tabindex="-1">Text identities <a class="header-anchor" href="#text-identities" aria-label="Permalink to &quot;Text identities&quot;">​</a></h2><p>These SHA-256 values identify the complete files; they do not certify semantic correctness or empirical effectiveness.</p><p><strong>Current Chinese text (reworded v2, 19 November 2026)</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5747a277dbf5a5cfb1583c0a172c3361710f4efee17d707ceb6151ce8cbaba3e</span></span></code></pre></div><p><strong>Chinese v2 text of 16 November 2026, which the English edition translates</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c</span></span></code></pre></div><p><strong>English reference reading edition</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb</span></span></code></pre></div><p><strong>Original supplied English file</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>f59bcdb483027736ef973b43ffc0c0ce37d9cb5e67ab3f05c6c67d22a62e65a1</span></span></code></pre></div><h2 id="explanatory-coverage" tabindex="-1">Explanatory coverage <a class="header-anchor" href="#explanatory-coverage" aria-label="Permalink to &quot;Explanatory coverage&quot;">​</a></h2><p>The source text and <a href="/xi-kari-skill/handbook/en/guide/selected-guides.html">all 421 on-page reading lessons</a> are available in English, including the lessons’ examples, questions and answers, source notes, and figure descriptions. The English site also includes fourteen concept pages and eight case pages. Downloadable historical research manuscripts, source registers, excerpts, and original diagrams remain in Chinese and are labeled accordingly. The democratic-authorization page explicitly identifies its separately preserved older Chinese research report and evidence cutoff.</p>',23)])])}const u=a(s,[["render",o]]);export{g as __pageData,u as default};
